#: ВСЕ известные парсеру населённые пункты: города + сельские НП.
#: Города перекрывают одноимённые сёла (у них координаты точнее).
KZ_PLACES_ALL: dict[str, str] = {**KZ_SETTLEMENTS, **KZ_CITIES_ALL}


#: Снимок справочника на момент импорта. Воркер-подпроцесс знает ровно его,
#: поэтому родитель обязан передавать координаты всех НП, которых тут нет.
_KZ_PLACES_BUILTIN: dict[str, str] = {}


def _query_place_name(place: str) -> str:
    """Имя НП для ТЕКСТА поискового запроса: без скобочного уточнения области.

    «Кабанбай (Абай)» → «Кабанбай»: скобки нужны только для уникальности
    ключа в справочнике, Яндексу они ломают запрос. Гео-привязку даёт вьюпорт.
    """
    return re.sub(r"\s*\([^)]*\)\s*$", "", place).strip() or place

#: Рабочий список из 19 городов — то, что реально нужно для GT-покрытия.
#: Это KZ_CITIES (18 областных центров и крупнейших) + Талдыкорган.
#: Именно он идёт по умолчанию в --all-cities; все 96 — через `--cities all`.
KZ_CITIES_MAJOR: dict[str, str] = {
    **KZ_CITIES,
    "Талдыкорган": KZ_CITIES_EXTRA["Талдыкорган"],
}


#: Куда fetch_osm_places.py кладёт выгрузку населённых пунктов из OSM.
OSM_PLACES_FILE = "kz_osm_places.json"

#: Куда fetch_wikidata_places.py кладёт выгрузку из Wikidata (данные Википедии).
WIKI_PLACES_FILE = "wikidata_places.json"


def load_osm_places(path: str | Path = OSM_PLACES_FILE) -> list[str]:
    """Подключить справочник НП из OSM (`--cities osm`) и вернуть их имена.

    Встроенные KZ_SETTLEMENTS собраны вручную и покрывают сотни НП, а в OSM
    их тысячи. Файл готовится отдельным скриптом `fetch_osm_places.py` —
    парсер сам в интернет за ним не ходит.

    Имена кладём в PLACES_ALL, чтобы `set_viewport(city=...)` нашёл по ним
    координаты. Свои (выверенные) координаты приоритетнее: если такой НП уже
    known, запись из OSM его не перетирает.
    """
    p = Path(path)
    if not p.exists():
        script = ("fetch_wikidata_places.py" if "wikidata" in p.name
                  else "fetch_osm_places.py")
        raise SystemExit(
            f"Нет файла {p} — справочник ещё не выкачан.\n"
            f"Сделай это один раз:  python3 {script}\n"
            f"(скрипту нужен интернет; парсер сам туда не ходит)")
    try:
        data = json.loads(p.read_text(encoding="utf-8"))
    except Exception as exc:
        raise SystemExit(f"Файл {p} не читается как JSON: {exc}")
    if not isinstance(data, dict) or not data:
        raise SystemExit(f"Файл {p} пуст или не словарь «имя: lon,lat»")

    names: list[str] = []
    added = 0
    for name, ll in data.items():
        name = str(name).strip()
        if not name or not isinstance(ll, str) or "," not in ll:
            continue
        names.append(name)
        if name not in PLACES_ALL:
            PLACES_ALL[name] = ll
            added += 1
    if added:
        _refresh_locality_index()
    log.info("OSM-справочник: %d НП из %s (новых для парсера: %d)",
             len(names), p, added)
    return names


def _names_from_file(path: str) -> list[str]:
    """`--cities @файл` — список НП из файла: по имени на строку, либо JSON."""
    p = Path(path)
    if not p.exists():
        raise SystemExit(f"Нет файла со списком НП: {p}")
    text = p.read_text(encoding="utf-8").strip()
    if text.startswith("{"):
        return load_osm_places(p)
    if text.startswith("["):
        try:
            return [str(x).strip() for x in json.loads(text) if str(x).strip()]
        except Exception as exc:
            raise SystemExit(f"{p}: не читается как JSON-список: {exc}")
    return [ln.strip() for ln in text.splitlines() if ln.strip()]


def resolve_city_list(spec: str | None) -> list[str]:
    """`--cities`: `major` (19, по умолчанию), `all` (96), `аулы` (сельские
    НП), `макс` (города + сёла разом) или свой список.

    Свой список — через запятую: `--cities "Алматы,Астана,Шымкент"`.
    """
    key = (spec or "").strip().lower()
    if not key or key in ("major", "main", "основные", "19"):
        return list(KZ_CITIES_MAJOR.keys())
    if key in ("all", "все", "города", "96"):
        return list(KZ_CITIES_ALL.keys())
    if key in ("аулы", "аул", "села", "сёла", "село", "aul", "selo", "rural",
               "деревни"):
        return list(KZ_SETTLEMENTS.keys())
    if key in ("макс", "max", "всё", "полный", "full", "everything", "вся"):
        return list(PLACES_ALL.keys())
    # Справочник из OpenStreetMap (тысячи сёл и аулов) — см. fetch_osm_places.py
    if key in ("osm", "осм", "овермап", "оsm"):
        return load_osm_places()
    # Справочник из Wikidata — структурированных данных Википедии.
    # См. fetch_wikidata_places.py.
    if key in ("wiki", "вики", "wikidata", "викидата", "википедия"):
        return load_osm_places(WIKI_PLACES_FILE)
    # Свой список из файла: --cities @places.txt (или @places.json)
    if spec.strip().startswith("@"):
        return _names_from_file(spec.strip()[1:])
    names = [c.strip() for c in spec.split(",") if c.strip()]
    # Одиночное слово, которого нет ни среди спеков, ни среди известных НП —
    # почти наверняка опечатка в спеке («аулу» вместо «аулы»). Своё название
    # НП тоже возможно, поэтому не падаем, но говорим об этом громко: иначе
    # вьюпорт молча встанет в центр страны и прогон даст мусор.
    if len(names) == 1 and names[0] not in PLACES_ALL:
        log.warning("«%s» — не спек и не известный парсеру НП. Спеки: "
                    "major, all, аулы, макс, osm, @файл. Если это название "
                    "населённого пункта, вьюпорт будет по центру страны — "
                    "выдача может уехать не туда.", names[0])
    return names

KZ_COUNTRY_LL = "66.9237,48.0196"   # весь Казахстан (регион 159), использовать с z=5
DEFAULT_CITY_Z = 12                 # зум для сбора по городу

# Grid-свип: Яндекс отдаёт ограниченное число результатов на один вьюпорт.
# Чтобы собрать БОЛЬШЕ, проходим сеткой вьюпортов по площади города.
GRID_SPAN_LON = 0.34   # ширина охвата города по долготе (°) ≈ 25 км
GRID_SPAN_LAT = 0.22   # высота охвата по широте (°)
GRID_TILE_Z = 14       # зум для отдельного тайла (плотнее = больше на тайл)


def viewport_grid(center_ll: str, n: int,
                  span_lon: float = GRID_SPAN_LON,
                  span_lat: float = GRID_SPAN_LAT) -> list[str]:
    """Сетка n×n центров вьюпортов вокруг center_ll ('lon,lat')."""
    try:
        lon0, lat0 = (float(x) for x in center_ll.split(","))
    except (ValueError, AttributeError):
        return [center_ll]
    if n <= 1:
        return [center_ll]
    tiles: list[str] = []
    for iy in range(n):
        for ix in range(n):
            fx = ix / (n - 1) - 0.5
            fy = iy / (n - 1) - 0.5
            lon = lon0 + fx * span_lon
            lat = lat0 + fy * span_lat
            tiles.append(f"{lon:.4f},{lat:.4f}")
    return tiles


