def _point_in_polygon(lon: float, lat: float,
                      poly: list[tuple[float, float]]) -> bool:
    """Точка внутри полигона (ray casting)."""
    n = len(poly)
    if n < 3:
        return True
    inside = False
    j = n - 1
    for i in range(n):
        xi, yi = poly[i]
        xj, yj = poly[j]
        # Ребро пересекает горизонтальный луч из точки вправо?
        if (yi > lat) != (yj > lat):
            x_cross = xi + (lat - yi) * (xj - xi) / (yj - yi)
            if lon < x_cross:
                inside = not inside
        j = i
    return inside


def _point_in_region(lon: float, lat: float) -> bool:
    """Точка внутри ЛЮБОЙ из активных стран. Без полигонов — True."""
    if not BORDERS:
        return True
    return any(_point_in_polygon(lon, lat, poly) for poly in BORDERS)


def _tile_in_region(lon: float, lat: float, span: float) -> bool:
    """Тайл (центр + span) задевает территорию активных стран?

    Проверка по углам даёт «буфер» в полтайла: приграничные сёла не теряем,
    даже если центр тайла формально за границей.
    """
    if not BORDERS:
        return True
    h = span / 2.0
    for dx, dy in ((0, 0), (-h, -h), (-h, h), (h, -h), (h, h)):
        if _point_in_region(lon + dx, lat + dy):
            return True
    return False


def _zoom_for_span(span_deg: float, lat: float = 48.0,
                   overlap: float = 1.35) -> int:
    """Подобрать зум карты так, чтобы видимое окно накрыло тайл целиком.

    Калибровка span(z) ≈ 1500/2^z° снята с реального URL Яндекс.Карт и
    описывает охват ПО ДОЛГОТЕ. По широте окно накрывает меньше: в проекции
    Меркатора градус широты «дороже» градуса долготы в cos(lat) раз, а окно
    браузера вдобавок шире, чем выше. Раньше это не учитывалось совсем, и при
    дефолтном шаге между рядами тайлов оставались непросмотренные полосы —
    тем шире, чем севернее.

    Поправку берём по cos(lat): точных пропорций окна мы не знаем, но
    направление ошибки известно, и эта поправка расширяет окно ровно на один
    уровень зума. Лишнее перекрытие безвредно — дедуп уберёт; пропущенная
    полоса необратима.
    """
    lat_scale = max(0.3, math.cos(math.radians(max(-85.0, min(85.0, lat)))))
    target = max(0.01, span_deg * overlap / lat_scale)
    z = int(math.floor(math.log2(1500.0 / target)))
    return max(4, min(17, z))


def country_grid(step_deg: float = COUNTRY_STEP_DEG,
                 bbox: tuple[float, float, float, float] | None = None,
                 clip: bool = True) -> list[str]:
    """Сетка вьюпортов по территории АКТИВНЫХ стран (для сплошного сбора).

    clip=True (по умолчанию) выбрасывает тайлы вне их границ: Каспий, Россия,
    Китай, Туркмения — это заметная доля прямоугольников bbox.

    Сетка единая для всех стран: узлы считаются от общего юго-западного угла,
    поэтому соседние страны стыкуются без нахлёста, а `--routes` и `--country`
    ложатся на одну решётку и дедуплицируются между собой.
    """
    boxes = [bbox] if bbox else (BBOXES or [KZ_BBOX])
    step = max(0.03, float(step_deg))   # защита от слишком мелкого шага
    olon, olat = _grid_origin()
    seen: dict[str, None] = {}
    for lon_min, lat_min, lon_max, lat_max in boxes:
        # Прижимаем края бокса к общей решётке, чтобы у разных стран узлы
        # совпадали, а не расходились на полшага.
        i0 = math.floor((lon_min - olon) / step)
        j0 = math.floor((lat_min - olat) / step)
        i1 = math.ceil((lon_max - olon) / step)
        j1 = math.ceil((lat_max - olat) / step)
        for j in range(j0, j1 + 1):
            lat = olat + j * step
            for i in range(i0, i1 + 1):
                lon = olon + i * step
                if clip and not _tile_in_region(lon, lat, step):
                    continue
                seen[f"{lon:.4f},{lat:.4f}"] = None
    return list(seen)


def _grid_origin() -> tuple[float, float]:
    """Юго-западный угол общей решётки — минимум по всем активным странам."""
    boxes = BBOXES or [KZ_BBOX]
    return min(b[0] for b in boxes), min(b[1] for b in boxes)


def _grid_snap(lon: float, lat: float, step: float) -> tuple[int, int]:
    """Индекс ячейки общей сетки для точки (та же решётка, что country_grid)."""
    lon_min, lat_min = _grid_origin()
    return round((lon - lon_min) / step), round((lat - lat_min) / step)


