# ---------------------------------------------------------------------------
# ТРИ СТРАНЫ: Казахстан, Узбекистан, Киргизия
#
# Раньше всё было завязано на Казахстан намертво. Теперь страна — это запись
# в реестре, а рабочие структуры (`PLACES_ALL`, `BORDERS`, `BBOXES`, `ROUTES`)
# собираются объединением по АКТИВНЫМ странам. Какие активны — задаёт
# `--countries` (по умолчанию все три).
#
# Что это меняет по сути: Ташкент и Бишкек перестали быть «заграницей» и
# больше не выбрасываются фильтром адресов; сетка национального свипа идёт по
# трём странам; вьюпорт ищет НП во всех трёх справочниках.
# ---------------------------------------------------------------------------

@dataclass(frozen=True)
class Country:
    """Одна страна сбора: где искать, чем ограничивать, что обходить."""
    code: str                                   # kz / uz / kg
    name: str                                   # человеческое имя
    tld: str                                    # домен Яндекса для неё
    center_ll: str                              # центр страны (lon,lat) для z=5
    bbox: tuple[float, float, float, float]     # lon_min, lat_min, lon_max, lat_max
    border: list[tuple[float, float]]           # полигон границы (lon, lat)
    cities: dict[str, str]                      # города: имя → "lon,lat"
    settlements: dict[str, str]                 # сёла/аулы/кишлаки
    routes: list[tuple[str, list[tuple[float, float]]]]

    @property
    def places(self) -> dict[str, str]:
        """Все НП страны. Город перекрывает одноимённое село: у него точнее."""
        return {**self.settlements, **self.cities}


COUNTRIES: dict[str, Country] = {
    "kz": Country(
        code="kz", name="Казахстан", tld="kz",
        center_ll=KZ_COUNTRY_LL, bbox=KZ_BBOX, border=KZ_BORDER,
        cities=KZ_CITIES_ALL, settlements=KZ_SETTLEMENTS, routes=KZ_ROUTES,
    ),
    "uz": Country(
        code="uz", name="Узбекистан", tld="uz",
        center_ll=UZ_COUNTRY_LL, bbox=UZ_BBOX, border=UZ_BORDER,
        cities=UZ_CITIES, settlements=UZ_SETTLEMENTS, routes=UZ_ROUTES,
    ),
    "kg": Country(
        code="kg", name="Киргизия", tld="kz",   # yandex.kg нет; Карты КР отдаёт .kz
        center_ll=KG_COUNTRY_LL, bbox=KG_BBOX, border=KG_BORDER,
        cities=KG_CITIES, settlements=KG_SETTLEMENTS, routes=KG_ROUTES,
    ),
}

#: Активные страны. Меняется флагом `--countries`.
ACTIVE_COUNTRIES: list[str] = ["kz", "uz", "kg"]

#: Рабочие объединения по активным странам — пересобираются set_countries().
PLACES_ALL: dict[str, str] = {}
BORDERS: list[list[tuple[float, float]]] = []
BBOXES: list[tuple[float, float, float, float]] = []
ROUTES: list[tuple[str, list[tuple[float, float]]]] = []


def resolve_countries(spec: str | None) -> list[str]:
    """`--countries`: «kz», «kz,uz», «все» (по умолчанию — все три)."""
    key = (spec or "").strip().lower()
    if not key or key in ("все", "all", "всё", "три"):
        return list(COUNTRIES)
    out: list[str] = []
    aliases = {"казахстан": "kz", "узбекистан": "uz", "киргизия": "kg",
               "кыргызстан": "kg", "kyrgyzstan": "kg", "uzbekistan": "uz",
               "kazakhstan": "kz", "кз": "kz", "уз": "uz", "кг": "kg"}
    for part in key.replace(" ", "").split(","):
        if not part:
            continue
        code = aliases.get(part, part)
        if code not in COUNTRIES:
            raise SystemExit(
                f"Неизвестная страна: «{part}». Доступны: "
                f"{', '.join(f'{c} ({COUNTRIES[c].name})' for c in COUNTRIES)}.")
        if code not in out:
            out.append(code)
    return out or list(COUNTRIES)


def set_countries(codes: list[str] | None = None) -> None:
    """Переключить активные страны и пересобрать рабочие объединения."""
    global ACTIVE_COUNTRIES, PLACES_ALL, BORDERS, BBOXES, ROUTES
    ACTIVE_COUNTRIES = [c for c in (codes or list(COUNTRIES)) if c in COUNTRIES] \
        or list(COUNTRIES)
    places: dict[str, str] = {}
    BORDERS = []
    BBOXES = []
    ROUTES = []
    for code in ACTIVE_COUNTRIES:
        c = COUNTRIES[code]
        # Одноимённые НП в разных странах: ключ получает уточнение, иначе
        # «Актау» из одной страны затирал бы «Актау» из другой.
        for name, ll in c.places.items():
            key = name if name not in places else f"{name} [{c.code.upper()}]"
            places[key] = ll
        if len(c.border) >= 3:
            BORDERS.append(c.border)
        BBOXES.append(c.bbox)
        ROUTES.extend(c.routes)
    PLACES_ALL = places
    _refresh_locality_index()


def route_tiles(step_deg: float = COUNTRY_STEP_DEG, corridor: int = 3,
                clip: bool = True) -> list[str]:
    """Тайлы коридоров вдоль магистралей KZ_ROUTES (для --routes).

    Каждый сегмент трассы сэмплируется чаще шага сетки, пробы снапятся к
    национальной решётке; corridor — ширина коридора в тайлах (3 = тайл трассы
    + по одному с каждой стороны, страховка от неточных опорных точек).
    Тайлы дедуплицируются между трассами и режутся полигоном границы.
    """
    step = max(0.03, float(step_deg))
    half = max(0, (max(1, int(corridor)) - 1) // 2)
    lon_min, lat_min = _grid_origin()
    cells: dict[tuple[int, int], None] = {}   # упорядоченное множество
    for _name, pts in (ROUTES or KZ_ROUTES):
        for (lon1, lat1), (lon2, lat2) in zip(pts, pts[1:]):
            d = max(abs(lon2 - lon1), abs(lat2 - lat1))
            n = max(1, int(math.ceil(d / (step * 0.6))))
            for k in range(n + 1):
                t = k / n
                ci, cj = _grid_snap(lon1 + (lon2 - lon1) * t,
                                    lat1 + (lat2 - lat1) * t, step)
                for di in range(-half, half + 1):
                    for dj in range(-half, half + 1):
                        cells[(ci + di, cj + dj)] = None
    tiles: list[str] = []
    for ci, cj in cells:
        lon, lat = lon_min + ci * step, lat_min + cj * step
        if not clip or _tile_in_region(lon, lat, step):
            tiles.append(f"{lon:.4f},{lat:.4f}")
    return tiles


# Маркеры ЗАРУБЕЖНОГО адреса в выдаче. Приграничные тайлы (Сарыагаш/Ташкент —
# 20 км; Кордай/Бишкек — 25 км) неизбежно захватывают чужие города во вьюпорт,
# и без фильтра свип granицы тащил бы тысячи узбекских/киргизских точек.
# Яндекс у организаций вне страны поиска пишет страну/регион в адресе — по ним
# и режем. Казахстанские адреса этих маркеров не содержат.
_FOREIGN_ADDR_RE = re.compile(
    # Казахстан, Узбекистан и Киргизия — ЗОНА СБОРА, их маркеры сюда не
    # входят. Чужое — всё остальное: Россия, Китай, Таджикистан, Туркмения,
    # Афганистан. Города пишем с правой границей слова, иначе «Ташкент»
    # совпадёт с «Ташкентская улица», а таких улиц много во всех трёх странах.
    r"(?:\bРоссия\b|\bКитай\b|\bСиньцзян|\bТаджикистан\b|\bТуркменистан\b"
    r"|\bАфганистан\b|\bМонголия\b"
    r"|\bДушанбе\b|\bХуджанд\b|\bКуляб\b|\bАшхабад\b|\bТуркменабад\b"
    r"|\bМазари-Шариф\b|\bКабул\b|\bКашгар\b|\bУрумчи\b"
    # Зарубежные регионы — по слову «обл/край/велаят/автономн», чтобы не
    # цеплять улицы «Омская», «Самарская» и т.п.
    r"|\bОмская обл|\bНовосибирская обл|\bОренбургская обл"
    r"|\bАстраханская обл|\bСамарская обл|\bСаратовская обл"
    r"|\bВолгоградская обл|\bЧелябинская обл|\bКурганская обл"
    r"|\bТюменская обл|\bАлтайский край|\bРеспублика Алтай|\bРесп\. Алтай"
    r"|\bСогдийская обл|\bХатлонская обл|\bГорно-Бадахшанская"
    r"|\bИли-Казахская|\bвелаят)",
    re.IGNORECASE,
)

# Таймзона/локаль браузера должны соответствовать домену (анти-фрод консистентность).
DOMAIN_TZ: dict[str, str] = {
    "yandex.kz": "Asia/Almaty",
    "yandex.ru": "Europe/Moscow",
    "yandex.com": "Europe/Moscow",
    "yandex.by": "Europe/Minsk",
    "yandex.uz": "Asia/Tashkent",
    "yandex.com.tr": "Europe/Istanbul",
}
DOMAIN_LOCALE: dict[str, str] = {
    "yandex.kz": "ru-RU",
    "yandex.ru": "ru-RU",
    "yandex.com": "en-US",
    "yandex.by": "ru-RU",
    "yandex.uz": "ru-RU",
    "yandex.com.tr": "tr-TR",
}

# Активный вьюпорт (устанавливается из --city / --ll в main()).
MAP_LL: str | None = None
MAP_Z: int = DEFAULT_CITY_Z


def set_domain(code: str | None) -> None:
    """Установить активный хост/язык по короткому коду TLD (kz/ru/com/…)."""
    global DOMAIN, LANG
    host, lang, _, _ = DOMAIN_REGISTRY.get((code or "kz").lower(), DOMAIN_REGISTRY["kz"])
    DOMAIN, LANG = host, lang


def set_viewport(city: str | None = None, ll: str | None = None, z: int | None = None) -> None:
    """Установить центр карты (ll=lon,lat) и зум для гео-привязки выдачи к KZ."""
    global MAP_LL, MAP_Z
    if ll:
        MAP_LL, MAP_Z = ll, (z or DEFAULT_CITY_Z)
    elif city and city in PLACES_ALL:
        MAP_LL, MAP_Z = PLACES_ALL[city], (z or DEFAULT_CITY_Z)
    else:
        # Нет города/координат — центрируемся на всей стране домена, если известно.
        _, _, country_ll, country_z = DOMAIN_REGISTRY.get(
            _tld_of(DOMAIN), DOMAIN_REGISTRY["kz"]
        )
        MAP_LL, MAP_Z = country_ll, (z or country_z)


def _tld_of(host: str) -> str:
    """yandex.kz -> kz, yandex.com.tr -> tr, yandex.com -> com."""
    for code, (h, *_rest) in DOMAIN_REGISTRY.items():
        if h == host:
            return code
    return "kz"


def base_url() -> str:
    """Базовый адрес. YAMAP_BASE_URL подменяет хост — так сквозной тест гоняет
    НАСТОЯЩИЙ парсер против локального макета Яндекса. Без такой точки подмены
    проверить всю цепочку (поиск → скролл → разбор → книга) нечем, и ошибки
    вылезают уже у пользователя."""
    override = os.environ.get("YAMAP_BASE_URL")
    return override.rstrip("/") if override else f"https://{DOMAIN}"


def maps_url() -> str:
    return f"{base_url()}/maps/"


def org_url(seoname: str, org_id: str) -> str:
    """Ссылка на карточку организации (канонизируется на yandex.com, но любой хост резолвит)."""
    return f"{base_url()}/maps/org/{seoname}/{org_id}/"


def search_url(query: str, with_viewport: bool = True) -> str:
    """URL поиска с языком и (опционально) закреплённым вьюпортом для гео-привязки."""
    u = f"{base_url()}/maps/?text={urllib.parse.quote(query)}&lang={LANG}"
    if with_viewport and MAP_LL:
        u += f"&ll={MAP_LL}&z={MAP_Z}"
    return u


# ---------------------------------------------------------------------------
# ОПЦИОНАЛЬНЫЕ УСКОРИТЕЛИ. По умолчанию ВЫКЛЮЧЕНЫ — основной алгоритм сбора
# (ввод в строку поиска + скролл выдачи) остаётся ровно таким, каким прошёл
# боевой прогон. Включаются флагами и при любом сбое молча откатываются на
# обычный путь, поэтому включение не может «сломать» сбор, только ускорить.
# ---------------------------------------------------------------------------

#: `--url-only` — не печатать запрос в строку поиска, сразу идти по URL.
#: Экономит 1-3 с на запросе и убирает класс багов со склейкой запросов;
#: платим тем, что переход по готовой ссылке чуть менее «человеческий».
URL_ONLY = False

#: `--fast-api` — дёргать внутренний JSON-API из УЖЕ ОТКРЫТОЙ вкладки
#: (fetch внутри страницы), вместо прокрутки выдачи. Куки, токены и заголовки
#: при этом настоящие — для Яндекса это запрос его собственного фронтенда.
FAST_API = False

#: Жёсткий потолок страниц на запрос — страховка от бесконечного цикла.
#: Рабочее число страниц считается из запрошенного лимита (-n), так что при
#: обычных лимитах сюда не упираемся.
FAST_API_MAX_PAGES = 400

#: fetch выполняется В КОНТЕКСТЕ СТРАНИЦЫ: тот же origin, те же куки.
_FAST_API_JS = """
async (url) => {
  try {
    const r = await fetch(url, {
      credentials: 'include',
      headers: {'Accept': 'application/json, text/plain, */*'},
    });
    const text = await r.text();
    if (!r.ok) return {ok: false, status: r.status, body: text.slice(0, 300)};
    try { return {ok: true, json: JSON.parse(text)}; }
    catch (e) { return {ok: false, status: r.status, body: text.slice(0, 300)}; }
  } catch (e) { return {ok: false, status: -1, body: String(e)}; }
}
"""


def api_search_url(query: str, page_no: int = 0) -> str:
    """Обобщённый URL внутреннего API поиска (запасной, когда шаблона нет).

    Настоящий Яндекс ждёт в этом запросе ещё и сессионные параметры, поэтому
    основной путь — шаблон из перехваченного запроса самой страницы
    (см. `_ApiCollector.last_url`), а этот URL нужен как запасной вариант.
    """
    u = (f"{base_url()}/maps/api/search?text={urllib.parse.quote(query)}"
         f"&lang={LANG}&page={page_no}")
    if MAP_LL:
        u += f"&ll={MAP_LL}&z={MAP_Z}"
    return u


def _bump_page(url: str, page_no: int, page_size: int = 20) -> str:
    """Поставить в URL нужную страницу, каким бы параметром она ни звалась.

    Яндекс листает то `page`, то `skip`/`offset` — подменяем тот, что есть,
    а если нет ни одного, дописываем `page`.

    Строку запроса разбираем ВРУЧНУЮ по верхнеуровневым «&», а не регуляркой
    по всему URL и не через urlencode: регулярка правила «page=» внутри
    вложенного URL в значении параметра, а urlencode перекодировал бы
    значения — для подписанного запроса Яндекса это смерть. Значения при
    таком разборе остаются байт в байт.
    """
    head, sep, query = url.partition("?")
    if not sep:
        return f"{url}?page={page_no}"
    pairs = query.split("&")

    def _set(key: str, value: int) -> str | None:
        out, done = [], False
        for pair in pairs:
            if not done and pair.split("=", 1)[0] == key:
                out.append(f"{key}={value}")
                done = True
            else:
                out.append(pair)
        return f"{head}?{'&'.join(out)}" if done else None

    for key, mult in (("page", 1), ("p", 1),
                      ("skip", page_size), ("offset", page_size)):
        got = _set(key, page_no * mult)
        if got is not None:
            return got
    return f"{url}&page={page_no}"


def _has_more(data: dict) -> bool | None:
    """Флаг «есть ещё страницы», если он вообще есть в ответе.

    Ищем и на верхнем уровне, и во вложенном `data` (items лежат то там, то
    там), и принимаем не только настоящий False, но и строку/ноль.
    """
    inner = data.get("data") if isinstance(data.get("data"), dict) else {}
    for holder in (data, inner):
        for key in ("hasMore", "has_more", "hasNextPage"):
            if key in holder:
                v = holder[key]
                if isinstance(v, str):
                    return v.strip().lower() not in ("false", "0", "")
                return bool(v)
    return None


def _api_template_for(collector: "_ApiCollector | None", query: str) -> str:
    """Шаблон запроса к API из перехвата — если он ТОЧНО про наш запрос.

    `last_url` перезаписывается любым подходящим ответом, включая карточку
    организации и запрос по ещё недопечатанному тексту. Спагинировать чужой
    запрос — значит молча собрать не то, поэтому сверяем `text=`.
    """
    url = getattr(collector, "last_url", "") or ""
    if not url:
        return ""
    m = re.search(r"[?&]text=([^&]*)", url)
    if m:
        try:
            got = urllib.parse.unquote_plus(m.group(1)).strip().casefold()
        except Exception:
            got = ""
        want = (query or "").strip().casefold()
        if got and want and got not in want and want not in got:
            log.debug("fast-api: перехваченный шаблон про «%s», а мы ищем «%s» "
                      "— шаблон не беру", got, query)
            return ""
    return url


def _fast_api_fetch(page: Page, url: str) -> dict | None:
    """Один запрос к API из контекста страницы. None — не вышло."""
    try:
        res = page.evaluate(_FAST_API_JS, url)
    except Exception as exc:
        log.debug("fast-api: evaluate упал: %s", exc)
        return None
    if not isinstance(res, dict) or not res.get("ok"):
        log.debug("fast-api: ответ не JSON (status=%s) %s",
                  (res or {}).get("status"), str((res or {}).get("body"))[:120])
        return None
    data = res.get("json")
    return data if isinstance(data, dict) else None


def _collect_via_api(page: Page, query: str, max_results: int,
                     collector: "_ApiCollector | None" = None,
                     on_org: Any = None) -> list[Organization] | None:
    """Собрать выдачу постраничными запросами к API. None — путь не сработал.

    None (а не пустой список) означает «откатись на обычный сбор». Пустой
    список возвращаем ТОЛЬКО когда API прямо сказал, что тут ноль результатов:
    перепутать эти два случая — значит принять молчание сломанного API за
    честное «здесь ничего нет» и оставить дыру в покрытии, которую докачка
    уже не закроет.

    Поэтому откатываемся всегда, когда собранное может оказаться неполным:
    ответ не разобрался, оборвался в середине, пагинация не двигается.
    """
    template = _api_template_for(collector, query)
    if template:
        log.debug("fast-api: шаблон из перехвата: %s", template.split("?")[0])

    orgs: list[Organization] = []
    seen: set[str] = set()
    total_expected = 0
    page_size = 0
    # Сколько страниц может понадобиться под запрошенный лимит. Раньше потолок
    # был жёстким (40 страниц ≈ 800 организаций) и срабатывал молча: при
    # `-n 5000` быстрый путь отдавал 800 и рапортовал об успехе.
    want = max_results if max_results and max_results > 0 else DEFAULT_MAX_RESULTS
    max_pages = max(2, min(FAST_API_MAX_PAGES, math.ceil(want / 20) + 2))

    def _incomplete() -> bool:
        """Есть основания считать, что собрано не всё."""
        return bool(total_expected) and len(orgs) < min(total_expected, want)

    for page_no in range(max_pages):
        url = (_bump_page(template, page_no, page_size or 20) if template
               else api_search_url(query, page_no))
        data = _fast_api_fetch(page, url)

        if data is None:
            if page_no == 0 or _incomplete():
                log.info("fast-api: ответ не получен на стр. %d (собрано %d"
                         "%s) — отдаю запрос обычному сбору", page_no, len(orgs),
                         f" из {total_expected}" if total_expected else "")
                return None
            break

        total = _extract_total_count(data)
        if total.isdigit():
            total_expected = max(total_expected, int(total))
        items = _find_api_items(data)

        if not items:
            if page_no == 0:
                # Ноль на первой же странице. «Честный ноль» — это только
                # явное total=0 в ответе; всё остальное (чужая форма JSON,
                # {"error": …} с кодом 200) — повод отдать запрос обычному
                # сбору, а не записать пустоту как результат.
                if total == "0":
                    log.info("fast-api: «%s» — API отвечает, что результатов нет", query)
                    return []
                log.info("fast-api: ответ есть, но организаций в нём не видно "
                         "(форма JSON незнакомая) — отдаю запрос обычному сбору")
                return None
            break

        page_size = max(page_size, len(items))
        added = 0
        for item in items:
            org = _org_from_item(item, total)
            if not org or not org.name:
                continue
            key = _dedup_key(org)
            if key in seen:
                continue
            seen.add(key)
            orgs.append(org)
            added += 1
            if on_org is not None:
                try:
                    on_org(org)
                except Exception:
                    pass
            if max_results and len(orgs) >= max_results:
                log.info("fast-api: «%s» — %d организаций (лимит)", query, len(orgs))
                return orgs

        if not added:
            # Страница вернула ровно то же, что прошлая: сервер не понял наш
            # параметр страницы. Если по его же счётчику собрано не всё —
            # это обрезка, а не конец выдачи.
            if _incomplete():
                log.info("fast-api: пагинация не двигается (стр. %d повторяет "
                         "предыдущую, собрано %d из %d) — отдаю запрос обычному "
                         "сбору", page_no, len(orgs), total_expected)
                return None
            break

        if _has_more(data) is False:
            break
        if total_expected and len(orgs) >= total_expected:
            break
    else:
        # Потолок страниц исчерпан, а выдача, похоже, не кончилась.
        if _incomplete():
            log.warning("fast-api: упёрся в потолок %d страниц, собрано %d из "
                        "%d — остальное недобрано", max_pages, len(orgs),
                        total_expected)

    log.info("fast-api: «%s» — %d организаций за %d стр.", query, len(orgs),
             page_no + 1)
    return orgs


# ---------------------------------------------------------------------------
# Постоянные отчёты и логи (сохраняются АВТОМАТИЧЕСКИ при каждом запуске)
#
#   logs/yamap_<дата>.log     — полный лог всего происходящего (DEBUG)
#   reports/<время>_<метка>.json + .md — отчёт по каждому прогону
#   reports/history.jsonl     — история всех запусков (по строке на прогон)
# ---------------------------------------------------------------------------

LOGS_DIR = Path("logs")
REPORTS_DIR = Path("reports")
_RUN_ERRORS: list[str] = []
_file_logging_ready = False


def setup_file_logging() -> Path:
    """Включить запись ВСЕХ логов в файл (в дополнение к консоли). Идемпотентно.

    Никогда не роняет запуск: при ошибке (нет прав, read-only ФС) молча
    остаёмся на консольном логировании.
    """
    global _file_logging_ready
    # У параллельных воркеров — свой файл: на Windows несколько процессов,
    # пишущих в один лог, дерутся за файл и мешают строки друг друга.
    worker = os.environ.get("YAMAP_WORKER")
    suffix = f"_w{worker}" if worker else ""
    log_path = LOGS_DIR / f"yamap_{time.strftime('%Y-%m-%d')}{suffix}.log"
    if _file_logging_ready:
        return log_path
    try:
        LOGS_DIR.mkdir(exist_ok=True)
        root = logging.getLogger()
        handler = logging.FileHandler(log_path, encoding="utf-8")
        handler.setLevel(logging.DEBUG)
        handler.setFormatter(logging.Formatter(
            "%(asctime)s  %(levelname)-8s  %(message)s", datefmt="%Y-%m-%d %H:%M:%S"))
        root.addHandler(handler)
        # В файл пишем DEBUG, но консоль оставляем на INFO (не засоряем вывод).
        root.setLevel(logging.DEBUG)
        for h in root.handlers:
            if isinstance(h, logging.StreamHandler) and not isinstance(h, logging.FileHandler):
                h.setLevel(logging.INFO)
        _file_logging_ready = True
        log.info("Логи пишутся в файл: %s", log_path)
    except Exception as exc:
        # Не критично — продолжаем с консольным логом.
        _file_logging_ready = True
        log.warning("Не удалось включить файловое логирование (%s) — только консоль", exc)
    return log_path


def record_error(msg: str) -> None:
    """Зафиксировать ошибку/инцидент для попадания в отчёт."""
    _RUN_ERRORS.append(f"{time.strftime('%H:%M:%S')}  {msg}")


def _report_to_md(r: dict) -> str:
    """Человекочитаемый Markdown-отчёт."""
    st = r.get("stats", {})
    lines = [
        f"# Отчёт YAmap — {r.get('timestamp', '')}",
        "",
        f"- **Режим:** {r.get('mode', '')}",
        f"- **Метка:** {r.get('label', '')}",
        f"- **Домен:** {r.get('domain', '')}  | язык: {r.get('lang', '')}",
        f"- **Вьюпорт:** ll={r.get('viewport_ll', '—')} z={r.get('viewport_z', '')}",
        f"- **Параметры:** max={r.get('max_results', '')}, api_intercept={r.get('api_intercept', '')}, "
        f"detail={r.get('detail', '')}, headless={r.get('headless', '')}, proxy={r.get('proxy', '')}",
        f"- **Длительность:** {r.get('duration_sec', '')} c",
        f"- **Капч поймано:** {r.get('captchas', 0)}",
        f"- **Файл результатов:** {r.get('output', '')}",
        "",
        "## Итоги сбора",
        "",
        f"- Всего организаций: **{st.get('total', 0)}**",
    ]
    cov = st.get("coverage", {})
    if cov:
        lines.append("- Покрытие полей:")
        for k, v in cov.items():
            lines.append(f"    - {k}: {v['count']} ({v['pct']}%)")
    if st.get("avg_rating"):
        lines.append(f"- Средний рейтинг: {st['avg_rating']}")
    if st.get("top_categories"):
        lines.append("- Топ категории:")
        for name, cnt in st["top_categories"]:
            lines.append(f"    - {name}: {cnt}")
    if r.get("per_query"):
        lines += ["", "## По запросам/категориям", ""]
        for q, cnt in r["per_query"].items():
            lines.append(f"- {q}: {cnt}")
    if r.get("errors"):
        lines += ["", "## Инциденты / ошибки", ""]
        for e in r["errors"]:
            lines.append(f"- {e}")
    return "\n".join(lines) + "\n"


def save_run_report(meta: dict, stats: dict) -> Path | None:
    """Сохранить отчёт о прогоне (JSON + Markdown) и дописать history.jsonl.

    Вызывается автоматически в конце каждого прогона (даже при частичном сборе).
    """
    try:
        REPORTS_DIR.mkdir(exist_ok=True)
        ts = time.strftime("%Y%m%d_%H%M%S")
        label = re.sub(r"[^\w-]+", "_", str(meta.get("label", "run")))[:40].strip("_") or "run"
        stem = f"{ts}_{label}"
        report = {
            "timestamp": time.strftime("%Y-%m-%d %H:%M:%S"),
            **meta,
            "stats": stats,
            "errors": list(_RUN_ERRORS),
        }
        (REPORTS_DIR / f"{stem}.json").write_text(
            json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8")
        (REPORTS_DIR / f"{stem}.md").write_text(_report_to_md(report), encoding="utf-8")
        with open(REPORTS_DIR / "history.jsonl", "a", encoding="utf-8") as f:
            f.write(json.dumps({
                "timestamp": report["timestamp"],
                "label": meta.get("label"),
                "mode": meta.get("mode"),
                "domain": meta.get("domain"),
                "total": stats.get("total"),
                "captchas": meta.get("captchas"),
                "duration_sec": meta.get("duration_sec"),
                "output": meta.get("output"),
                "errors": len(_RUN_ERRORS),
            }, ensure_ascii=False) + "\n")
        log.info("Отчёт сохранён: reports/%s.json (+ .md), история → reports/history.jsonl", stem)
        return REPORTS_DIR / f"{stem}.json"
    except Exception as exc:
        log.debug("Не удалось сохранить отчёт: %s", exc)
        return None


# ---------------------------------------------------------------------------
# Data model
# ---------------------------------------------------------------------------

@dataclass
class Organization:
    # --- базовые поля (порядок колонок сохраняется, новые поля добавляются в конец) ---
    name: str = ""
    address: str = ""
    phone: str = ""
    website: str = ""
    rating: str = ""
    reviews_count: str = ""
    category: str = ""
    working_hours: str = ""
    latitude: str = ""
    longitude: str = ""
    email: str = ""
    social_links: str = ""
    yandex_url: str = ""
    search_query: str = ""
    #: Слаг GT-категории (gt_zapravki, gt_produktovye, …) — чтобы выгрузку
    #: можно было сматчить со своей таблицей по ключу, а не по названию.
    gt_slug: str = ""
    #: Точный запрос, которым эту строку нашли («Кафе», «Ресторан», …).
    #: Отличается от search_query: там название категории («Поесть»), общее для
    #: нескольких запросов. Резюме считает выполненные запросы именно отсюда,
    #: иначе первый же запрос категории закрыл бы остальные её запросы.
    source_query: str = ""
    #: Город прогона. Именно прогона, а не разобранного адреса: так строка
    #: однозначно ложится в таблицу «город × категория».
    city: str = ""
    # --- расширенные поля: «снять все данные» с Яндекс.Карт ---
    # идентификаторы и ссылки
    org_id: str = ""             # items[].id (стабильный permalink/oid)
    seoname: str = ""            # items[].seoname (slug рубрики/организации)
    org_uri: str = ""            # items[].uri (ymapsbm1://org?oid=...)
    # названия
    short_name: str = ""         # items[].shortTitle
    legal_name: str = ""         # items[].name (юр. лицо, если отличается от title)
    # структурированный адрес
    full_address: str = ""       # items[].fullAddress (с городом)
    additional_address: str = "" # items[].additionalAddress (этаж/вход/в ТЦ)
    postal_code: str = ""        # compositeAddress.postalCode
    country: str = ""            # items[].country
    region_name: str = ""        # compositeAddress.region
    locality: str = ""           # compositeAddress.locality (город)
    district: str = ""           # compositeAddress.district (район)
    street: str = ""             # compositeAddress.street
    house: str = ""              # compositeAddress.house
    geo_id: str = ""             # items[].geoId (числовой ID региона)
    display_latitude: str = ""   # displayCoordinates[1] (координата метки)
    display_longitude: str = ""  # displayCoordinates[0]
    # контакты
    websites_all: str = ""       # items[].urls через "; " (website = urls[0])
    phone_types: str = ""        # phones[].type параллельно phone
    booking_url: str = ""        # links/businessLinks type=booking
    # классификация
    category_classes: str = ""   # categories[].class (стабильные слаги)
    category_seonames: str = ""  # categories[].seoname
    rubric_ids: str = ""         # rubricIds
    chain_id: str = ""           # chain.id
    chain_name: str = ""         # chain.name (сеть/бренд)
    # рейтинги (разделены с reviews_count)
    rating_count: str = ""       # ratingData.ratingCount (кол-во оценок-звёзд)
    # часы работы / статус
    is_open_now: str = ""        # currentWorkingStatus.isOpenNow -> да/нет
    current_status_text: str = "" # currentWorkingStatus.text
    round_the_clock: str = ""    # круглосуточно (да/"")
    tz_offset: str = ""          # items[].tzOffset (сек)
    status: str = ""             # items[].status (open/closed/temporarily_closed)
    temporarily_closed: str = "" # да, если status == temporarily_closed
    # атрибуты
    description: str = ""        # items[].description
    features: str = ""           # features[] в виде "имя: значение; ..."
    price_average: str = ""      # средний чек из subtitleItems
    # медиа
    photos_count: str = ""       # photos.count
    photo_url_template: str = "" # photos.urlTemplate (avatars.mds.yandex.net, %s = размер)
    logo_url: str = ""           # businessImages.logo.urlTemplate
    panorama_id: str = ""        # panorama.id
    # транспорт
    metro: str = ""              # metro[] "имя (расстояние)"
    stops: str = ""              # stops[] "имя (расстояние)"
    # реклама / верификация / провенанс
    is_advert: str = ""          # да, если advert != null (платное размещение)
    inn_tax_id: str = ""         # advert.ordInfo.client.tin (только у рекламы)
    awards: str = ""             # awards, напр. "goodPlaceYear:2024"
    is_verified: str = ""        # да, если владелец подтверждён (sources/businessProperties)
    # конверт запроса
    total_result_count: str = "" # data.totalResultCount по запросу


FIELDNAMES = [f.name for f in fields(Organization)]


def _normalize_for_dedup(text: str) -> str:
    """Нормализовать строку для дедупликации.

    'ул. Ленина, 5' и 'улица Ленина, 5' → одинаковый ключ.
    """
    s = text.lower().strip()
    # Стандартные сокращения
    s = re.sub(r'\bулица\b', 'ул', s)
    s = re.sub(r'\bпроспект\b', 'пр-т', s)
    s = re.sub(r'\bпереулок\b', 'пер', s)
    s = re.sub(r'\bбульвар\b', 'б-р', s)
    s = re.sub(r'\bпроезд\b', 'пр-д', s)
    s = re.sub(r'\bнабережная\b', 'наб', s)
    s = re.sub(r'\bплощадь\b', 'пл', s)
    s = re.sub(r'\bмикрорайон\b', 'мкр', s)
    # Убираем точки, лишние пробелы, запятые
    s = s.replace('.', '').replace(',', ' ')
    s = re.sub(r'\s+', ' ', s).strip()
    return s


def _dedup_key(org: Organization) -> str:
    """Ключ для дедупликации организации.

    Адрес нормализуется БЕЗ префикса города — иначе одна и та же организация
    из сниппета («Алматы, ул. Абая, 1») и из API («ул. Абая, 1») получит разные
    ключи и не сольётся/задублируется. Если адрес пуст (Яндекс иногда его не
    показывает) — различаем точки сети по ID или координатам, чтобы разные
    филиалы не схлопнулись в одну запись.
    """
    # ID организации у Яндекса — самая надёжная личность: он ОДИНАКОВ во всех
    # источниках (сниппет, SSR, внутренний API) и при этом различает филиалы
    # сети. Адрес слабее: источник может его не отдать, и тогда одна и та же
    # точка попадала в выгрузку дважды — с адресом и без. Имя в ключ не берём:
    # у одной точки оно может отличаться между источниками.
    if org.org_id:
        return f"id:{org.org_id}"
    name = _normalize_for_dedup(org.name)
    addr = _loose_addr(org.address)
    if addr:
        return f"{name}|{addr}"
    if org.latitude and org.longitude:
        return f"{name}|{org.latitude},{org.longitude}"
    return f"{name}|"


def _finalize_orgs(orgs: list["Organization"]) -> list["Organization"]:
    """Финальная подчистка перед сохранением: убрать записи без названия и дубли.

    Дубли не выбрасываем, а СЛИВАЕМ: одна и та же точка приходит из разных
    источников с разной полнотой (в сниппете есть рейтинг, в API — телефон и
    координаты). Прежний вариант «первый выиграл» терял то, что было только у
    второго.
    """
    out: list[Organization] = []
    index: dict[str, int] = {}
    for o in orgs:
        if not (o.name or "").strip():
            continue
        k = _dedup_key(o)
        # Запасной ключ «имя|адрес»: та же точка могла быть снята и без ID
        # (сниппет), и с ID (API) — это разные основные ключи, но одна строка.
        alias = ""
        addr = _loose_addr(o.address)
        if o.org_id and addr:
            alias = f"{_normalize_for_dedup(o.name)}|{addr}"
        pos = index.get(k)
        if pos is None and alias:
            cand = index.get(alias)
            # Alias («имя|адрес») — запасной ключ для склейки записи БЕЗ id с
            # записью С id. Но две РАЗНЫЕ организации с одинаковым именем и
            # адресом (сетевые АЗС и магазины в одном селе — типичный случай,
            # а в сёлах Яндекс часто отдаёт адресом одно лишь название НП)
            # имеют разные org_id, и склеивать их нельзя: вторая точка молча
            # исчезала из выгрузки. Берём alias, только если id не спорят.
            if cand is not None:
                other = out[cand].org_id or ""
                mine = o.org_id or ""
                if not mine or not other or mine == other:
                    pos = cand
        if pos is None:
            pos = len(out)
            index[k] = pos
            out.append(o)
        else:
            _merge_orgs(out[pos], o)
            index.setdefault(k, pos)
        if alias:
            index.setdefault(alias, pos)
    return out


# ---------------------------------------------------------------------------
# Proxy rotation
# ---------------------------------------------------------------------------

class ProxyRotator:
    """Ротация прокси-серверов для обхода блокировок.

    Форматы прокси:
      - http://host:port
      - http://user:pass@host:port
      - socks5://host:port
    """

    def __init__(self, proxies: list[str] | None = None):
        self._proxies = proxies or []
        # Стартовая позиция разная у разных воркеров. Иначе все N процессов
        # независимо создавали ротатор, брали next() и садились на ПЕРВУЮ
        # строку файла: пользователь дал десять прокси, а с точки зрения
        # Яндекса запросы шли с одного IP — то есть ровно то, от чего прокси
        # и заводили.
        try:
            worker = int(os.environ.get("YAMAP_WORKER") or 0)
        except ValueError:
            worker = 0
        self._index = (worker - 1) % len(proxies) if proxies and worker > 0 else 0
        self._fail_counts: dict[str, int] = {}

    @classmethod
    def from_file(cls, path: str) -> "ProxyRotator":
        """Загрузить прокси из файла (одна строка = один прокси)."""
        p = Path(path)
        if not p.exists():
            log.warning("Файл прокси не найден: %s", path)
            return cls([])
        lines = [
            line.strip() for line in p.read_text(encoding="utf-8").splitlines()
            if line.strip() and not line.strip().startswith("#")
        ]
        log.info("Загружено %d прокси из %s", len(lines), path)
        return cls(lines)

    @property
    def has_proxies(self) -> bool:
        return len(self._proxies) > 0

    def next(self) -> str | None:
        """Следующий прокси (round-robin)."""
        if not self._proxies:
            return None
        proxy = self._proxies[self._index % len(self._proxies)]
        self._index += 1
        return proxy

    def current(self) -> str | None:
        if not self._proxies:
            return None
        return self._proxies[(self._index - 1) % len(self._proxies)]

    def mark_failed(self, proxy: str) -> None:
        self._fail_counts[proxy] = self._fail_counts.get(proxy, 0) + 1
        if self._fail_counts[proxy] >= 3:
            log.warning("Прокси %s — 3 ошибки, удаляю из ротации", proxy)
            self._proxies = [p for p in self._proxies if p != proxy]
            self._fail_counts.pop(proxy, None)

    def to_playwright_arg(self, proxy_url: str) -> dict:
        """Конвертировать URL прокси в формат Playwright."""
        result: dict[str, str] = {"server": proxy_url}
        parsed = urllib.parse.urlparse(proxy_url)
        if parsed.username:
            result["username"] = parsed.username
        if parsed.password:
            result["password"] = parsed.password
        if parsed.username or parsed.password:
            result["server"] = f"{parsed.scheme}://{parsed.hostname}:{parsed.port}"
        return result


# Глобальный ротатор (инициализируется в main)
_proxy_rotator: ProxyRotator | None = None


def get_proxy_rotator() -> ProxyRotator:
    global _proxy_rotator
    if _proxy_rotator is None:
        _proxy_rotator = ProxyRotator()
    return _proxy_rotator


# ---------------------------------------------------------------------------
# CAPTCHA detection
# ---------------------------------------------------------------------------

_CAPTCHA_SELECTORS = [
    "[class*='captcha']",
    "[class*='Captcha']",
    "[class*='CheckboxCaptcha']",
    "#js-button",
    "[class*='smartcaptcha']",
    "iframe[src*='captcha']",
    "[class*='AdvancedCaptcha']",
]


def detect_captcha(page: Page) -> bool:
    """Проверить, показала ли страница CAPTCHA."""
    for sel in _CAPTCHA_SELECTORS:
        if page.locator(sel).count() > 0:
            return True
    # Дополнительно проверяем по URL
    if "showcaptcha" in page.url or "captcha" in page.url.lower():
        return True
    return False


def _bezier_mouse_move(page: Page, start_x: float, start_y: float,
                       end_x: float, end_y: float, steps: int = 15) -> None:
    """Двигаем мышь по кривой Безье (3 точки) — как человек.

    Прямые линии палятся как автоматизация. Человек двигает мышь по дуге
    с ускорением в начале и замедлением в конце.
    """
    # Контрольная точка — смещена вбок от прямой
    ctrl_x = (start_x + end_x) / 2 + random.randint(-80, 80)
    ctrl_y = (start_y + end_y) / 2 + random.randint(-60, 60)

    for i in range(steps + 1):
        t = i / steps
        # Квадратичная Безье: B(t) = (1-t)²·P0 + 2(1-t)t·P1 + t²·P2
        x = (1 - t) ** 2 * start_x + 2 * (1 - t) * t * ctrl_x + t ** 2 * end_x
        y = (1 - t) ** 2 * start_y + 2 * (1 - t) * t * ctrl_y + t ** 2 * end_y
        # Небольшой шум
        x += random.randint(-2, 2)
        y += random.randint(-2, 2)
        page.mouse.move(x, y)
        # Пауза: короткая в середине, длиннее в начале/конце (как человек)
        if i < 3 or i > steps - 3:
            page.wait_for_timeout(random.randint(20, 60))
        else:
            page.wait_for_timeout(random.randint(5, 20))


def _try_click_captcha(page: Page) -> bool:
    """Попробовать автоматически кликнуть 'Я не робот' (checkbox-капча).

    Использует Bezier-кривую для движения мыши — прямые линии палятся.
    """
    checkbox_sels = [
        "[class*='CheckboxCaptcha'] .CheckboxCaptcha-Button",
        "[class*='CheckboxCaptcha-Button']",
        "#js-button",
        "input[type='submit'][value*='робот']",
        "button:has-text('робот')",
        "[class*='captcha'] button",
        ".smartcaptcha input[type='checkbox']",
    ]
    for sel in checkbox_sels:
        try:
            btn = page.locator(sel).first
            if btn.count() > 0 and btn.is_visible():
                box = btn.bounding_box()
                if box:
                    # Стартуем из случайной точки на странице
                    start_x = random.randint(200, 600)
                    start_y = random.randint(100, 400)
                    page.mouse.move(start_x, start_y)
                    page.wait_for_timeout(random.randint(200, 500))

                    # Двигаем по Безье к кнопке
                    target_x = box["x"] + box["width"] / 2 + random.randint(-3, 3)
                    target_y = box["y"] + box["height"] / 2 + random.randint(-2, 2)
                    _bezier_mouse_move(page, start_x, start_y, target_x, target_y)

                    # Небольшая пауза перед кликом (человек "прицеливается")
                    page.wait_for_timeout(random.randint(100, 300))

                    # Клик по Безье-точке
                    page.mouse.click(target_x, target_y)
                else:
                    # Нет bounding box — обычный клик
                    btn.click()
                log.info("Автоклик по кнопке капчи: %s", sel)
                page.wait_for_timeout(3000)
                return not detect_captcha(page)
        except Exception:
            continue
    return False


def handle_captcha(page: Page, headless: bool) -> bool:
    """Обработать CAPTCHA: автоклик → сразу ручное решение.

    Стратегия без платных сервисов:
    1. Автоклик checkbox «Я не робот» (Bezier-мышь)
    2. Если не помогло — сразу просим решить вручную (не тратим время на reload)
    3. В headless — пауза + reload (надежда на протухание)

    Один раз решил вручную → persistent profile запоминает → следующий раз без капчи.

    Возвращает True если CAPTCHA решена, False если таймаут.
    """
    if not detect_captcha(page):
        return True

    log.warning("=" * 60)
    log.warning("ОБНАРУЖЕНА CAPTCHA!")

    # 1. Пробуем автоклик (checkbox «Я не робот») с Bezier-движением мыши
    if _try_click_captcha(page):
        log.info("CAPTCHA решена автокликом!")
        log.warning("=" * 60)
        return True

    # 2. Пауза + reload — иногда капча протухает после ожидания
    log.info("Пауза 15-25 сек + reload (капча может протухнуть)…")
    page.wait_for_timeout(random.randint(15000, 25000))
    try:
        page.reload(wait_until="domcontentloaded", timeout=20000)
        page.wait_for_timeout(random.randint(3000, 5000))
        if not detect_captcha(page):
            log.info("CAPTCHA исчезла после паузы и reload!")
            log.warning("=" * 60)
            return True
        # Ещё раз пробуем автоклик — может теперь простая форма
        if _try_click_captcha(page):
            log.info("CAPTCHA решена автокликом после reload!")
            log.warning("=" * 60)
            return True
    except Exception:
        pass

    # 3. Ручное решение / автоожидание
    if headless:
        # В headless ждём подольше — капча может протухнуть
        log.warning("Headless-режим: пауза 60 сек + reload…")
        page.wait_for_timeout(60000)
        try:
            page.reload(wait_until="domcontentloaded", timeout=20000)
            page.wait_for_timeout(5000)
            if not detect_captcha(page):
                log.info("CAPTCHA исчезла после паузы!")
                log.warning("=" * 60)
                return True
        except Exception:
            pass
    else:
        # В видимом браузере — СРАЗУ просим решить вручную
        log.warning("")
        log.warning("  >>> РЕШИТЕ КАПЧУ В БРАУЗЕРЕ! <<<")
        log.warning("  После решения парсер продолжит автоматически.")
        log.warning("  (persistent profile запомнит — следующий раз без капчи)")
        log.warning("")
        for i in range(60):  # 60 * 5 = 300 секунд (5 минут)
            page.wait_for_timeout(5000)
            if not detect_captcha(page):
                log.info("CAPTCHA решена! Продолжаем…")
                log.warning("=" * 60)
                return True
            if i > 0 and i % 12 == 0:
                log.info("Ожидание решения капчи… (%d сек)", i * 5)
        log.error("Таймаут ожидания решения CAPTCHA (5 мин)")

    log.warning("=" * 60)
    return not detect_captcha(page)


# ---------------------------------------------------------------------------
# Resume manager — продолжение с места остановки
# ---------------------------------------------------------------------------

class ResumeManager:
    """Менеджер докачки: загружает уже собранные данные из файла."""

    def __init__(self, path: Path | None = None):
        self._existing: dict[str, Organization] = {}
        self._completed_queries: set[str] = set()
        if path and path.exists():
            self._load(path)

    def _load(self, path: Path) -> None:
        """Загрузить существующий файл результатов."""
        suffix = path.suffix.lower()
        rows: list[dict] = []

        if suffix == ".csv":
            try:
                with open(path, "r", encoding="utf-8-sig") as f:
                    reader = csv.DictReader(f, delimiter=";")
                    rows = list(reader)
            except Exception as exc:
                log.warning("Не удалось прочитать CSV для резюме: %s", exc)
                return

        elif suffix == ".xlsx":
            try:
                from openpyxl import load_workbook
                wb = load_workbook(path, read_only=True)
                ws = wb.active
                if ws is None:
                    return
                headers = [cell.value for cell in next(ws.iter_rows(min_row=1, max_row=1))]
                for row in ws.iter_rows(min_row=2, values_only=True):
                    row_dict = {h: (v or "") for h, v in zip(headers, row) if h}
                    rows.append(row_dict)
                wb.close()
            except Exception as exc:
                log.warning("Не удалось прочитать XLSX для резюме: %s", exc)
                return

        elif suffix == ".json":
            try:
                data = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(data, list):
                    rows = data
                elif isinstance(data, dict) and "organizations" in data:
                    rows = data["organizations"]
            except Exception as exc:
                log.warning("Не удалось прочитать JSON для резюме: %s", exc)
                return

        # Маппинг русских заголовков на английские поля
        ru_to_en = {v: k for k, v in HEADERS_RU.items()}

        for row in rows:
            # Нормализуем ключи (могут быть русские заголовки из xlsx)
            norm = {}
            for k, v in row.items():
                en_key = ru_to_en.get(k, k)
                norm[en_key] = str(v) if v else ""

            org = Organization(**{f: norm.get(f, "") for f in FIELDNAMES if f in norm})
            # Ключ — ТОТ ЖЕ _dedup_key, что и в живом сборе (org_id важнее
            # имени+адреса). Старый ключ «имя|адрес» схлопывал разные точки
            # сети с одинаковым названием и пустым/общим адресом: 30 АЗС
            # «КазМунайГаз» вдоль трассы при чтении файла превращались в одну,
            # и следующее сохранение затирало остальные навсегда.
            if not ((org.name or "").strip() or org.org_id):
                continue
            self._existing[_dedup_key(org)] = org
            # source_query — точный запрос; search_query оставлен как
            # запасной вариант для файлов, снятых до его появления.
            q = norm.get("source_query", "") or norm.get("search_query", "")
            if q:
                self._completed_queries.add(q)

        log.info(
            "Резюме: загружено %d существующих организаций, %d выполненных запросов",
            len(self._existing), len(self._completed_queries),
        )

    @property
    def existing_count(self) -> int:
        return len(self._existing)

    def is_known(self, org: "Organization") -> bool:
        return _dedup_key(org) in self._existing

    def is_query_done(self, query: str) -> bool:
        return query in self._completed_queries

    def existing_orgs(self) -> list[Organization]:
        return list(self._existing.values())

    def existing_keys(self) -> set[str]:
        return set(self._existing.keys())


# ---------------------------------------------------------------------------
# Config file support (YAML/JSON)
# ---------------------------------------------------------------------------

#: Потолок организаций на один поисковый запрос/категорию. Яндекс на один вид
#: карты отдаёт заметно меньше, поэтому лимит фактически не режет выдачу —
#: он лишь страхует от бесконечного скролла.
DEFAULT_MAX_RESULTS = 5000
#: Для --country лимит СВОЙ и намеренно низкий: тайлов десятки тысяч, и упор
#: в лимит там означает «тайл плотный» → он делится на под-тайлы (quadtree).
COUNTRY_MAX_PER_TILE = 250

DEFAULT_CONFIG: dict[str, Any] = {
    "max_results": DEFAULT_MAX_RESULTS,
    "scroll_pause": 1.0,
    "headless": True,
    "detail": False,
    "api_intercept": False,
    "output": "results.xlsx",
    "proxy": None,
    "proxy_file": None,
    "city": None,
    "categories": None,
}


def load_config(path: str) -> dict[str, Any]:
    """Загрузить конфиг из YAML или JSON файла."""
    p = Path(path)
    if not p.exists():
        log.warning("Конфиг-файл не найден: %s", path)
        return {}

    text = p.read_text(encoding="utf-8")
    if p.suffix in (".yaml", ".yml"):
        try:
            import yaml
            return yaml.safe_load(text) or {}
        except ImportError:
            log.warning("PyYAML не установлен — пробую как JSON")
    try:
        return json.loads(text)
    except Exception as exc:
        log.warning("Ошибка чтения конфига %s: %s", path, exc)
        return {}


